param([switch]$RunNoPlant)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$entry=$PSScriptRoot
function Sha([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
$ids=@('DL1018_VAL_T1_C00_W07','DL1018_VAL_T1_C02_W09','DL1018_VAL_T1_C05_W12','DL1018_VAL_T1_C08_W15','DL1018_VAL_T2_C00_W10','DL1018_VAL_T2_C02_W12','DL1018_VAL_T2_C05_W15','DL1018_VAL_T2_C06_W00','DL1018_VAL_T3_C00_W13','DL1018_VAL_T3_C02_W15','DL1018_VAL_T3_C03_W00','DL1018_VAL_T3_C12_W09')
$csv=Import-Csv -LiteralPath (Join-Path $entry 'configs/scene_specs_screen12.csv');if($csv.Count -ne 12 -or (@($csv.scene_id) -join ',') -ne ($ids -join ',') -or @($csv|Where-Object split -ne 'VAL').Count -ne 0){throw 'Fixed VAL CSV scene scope mismatch.'}
$required=@('run_morph_dev2_screen12.m','launch_morph_dev2_screen12.ps1','prepare_manifest_no_plant.m','matlab/scenes/make_paired_screen12_scene.m','ATTITUDE_PHYS_INERTIA_SCREEN12_TASKBOOK_v1_ZH.md')
foreach($f in $required){if(-not(Test-Path -LiteralPath (Join-Path $entry $f) -PathType Leaf)){throw "Required file missing: $f"}}
$psTokens=$null;$psErrors=$null;[void][System.Management.Automation.Language.Parser]::ParseFile((Join-Path $entry 'launch_morph_dev2_screen12.ps1'),[ref]$psTokens,[ref]$psErrors);if($psErrors.Count -ne 0){throw 'Launcher PowerShell parse failed.'}
$runner=Get-Content -Raw -LiteralPath (Join-Path $entry 'run_morph_dev2_screen12.m');$scene=Get-Content -Raw -LiteralPath (Join-Path $entry 'matlab/scenes/make_paired_screen12_scene.m');$prep=Get-Content -Raw -LiteralPath (Join-Path $entry 'prepare_manifest_no_plant.m')
if(-not $runner.Contains('runnerCalls<24') -or -not $runner.Contains('Runner calls: %d / 24;') -or -not $runner.Contains('max_transitions)==480000') -or -not $runner.Contains("'reason',''") -or $runner.Contains('preflight_candidate_path') -or $runner.Contains('candidate.result') -or $runner.Contains('DL1018_TEST_')){throw 'Runner scope/status initialization gate failed.'}
if(-not $runner.Contains('~is_scalar_false(log.attitude_fusion_rbf_output_enabled)') -or -not $runner.Contains('~is_scalar_false(log.attitude_fusion_rbf_update_enabled)') -or -not $runner.Contains('~zero_axis_history(log.rbf_output_held,n)') -or -not $runner.Contains('~zero_scalar_history(log.rbf_weight_norm,n)') -or -not $runner.Contains('logical(tr.prepare.observer.updated)==logical(tr.is_attitude_event)') -or $runner.Contains('numel(log.attitude_fusion_rbf_output_enabled)~=n')){throw 'Candidate RBF trace dimension or event/update contract regressed.'}
if($scene.Contains('run_paired_observer_closed_loop') -or $scene.Contains('rk4_vehicle_step') -or $prep.Contains('run_paired_observer_closed_loop') -or $prep.Contains('rk4_vehicle_step') -or $prep.Contains('DL1018_TEST_')){throw 'No-Plant helper contains a closed-loop/TEST call.'}
if($runner.Contains('Count -ne 2') -or $runner.Contains('Where-Object status -ne complete).Count -ne 2')){throw 'Known failure-count predicate regression.'}
$base='experiments/attitude_physics_inertia_observer_20261025/paired_runner';$t3=Get-Content -Raw -LiteralPath (Join-Path $base 'root_review_v1/SOURCE_LOCK_MORPH_DEV2_T3_CONTINUATION_v1_FROZEN.json')|ConvertFrom-Json
$srcRoot=(Resolve-Path (Join-Path $base 'matlab')).Path;$copied=Get-ChildItem -Recurse -File -LiteralPath (Join-Path $entry 'matlab')|Where-Object{$_.Extension -eq '.m' -and $_.Name -ne 'make_paired_screen12_scene.m'};if($copied.Count -ne 39){throw "Expected 39 imported MATLAB sources; found $($copied.Count)."}
foreach($s in $t3.sources){$p=Join-Path $entry (Join-Path 'matlab' $s.relative_path.Substring(7));if((Sha $p) -ne $s.sha256){throw "Imported source SHA differs: $($s.relative_path)"}}
if($RunNoPlant){$matlab='C:\Program Files\MATLAB\R2025b\bin\matlab.exe';if((Sha $matlab) -ne '6dc32276086121e44edf4846f033066ba5b0fae9bad002d8917a411e0a59afa9'){throw 'MATLAB executable SHA mismatch.'};$cmd="run('$($entry.Replace('\','/'))/prepare_manifest_no_plant.m')";& $matlab -batch $cmd;if($LASTEXITCODE -ne 0){throw 'MATLAB no-Plant manifest generation failed.'}}
Write-Output 'SCREEN12_STATIC_PASS plant_runs=0 training_runs=0 TEST_accessed=false'
